  operate: (
    input: OperateInput
  ) => ReturnType<typeof getOperateInstruction> & SelfPlanAndSendFunctions;
  pauseToken: (
    input: PauseTokenInput
  ) => ReturnType<typeof getPauseTokenInstruction> & SelfPlanAndSendFunctions;
  pauseUser: (
    input: PauseUserInput
  ) => ReturnType<typeof getPauseUserInstruction> & SelfPlanAndSendFunctions;
  preOperate: (
    input: PreOperateInput
  ) => ReturnType<typeof getPreOperateInstruction> & SelfPlanAndSendFunctions;
  unpauseToken: (
    input: UnpauseTokenInput
  ) => ReturnType<typeof getUnpauseTokenInstruction> & SelfPlanAndSendFunctions;
  unpauseUser: (
    input: UnpauseUserInput
  ) => ReturnType<typeof getUnpauseUserInstruction> & SelfPlanAndSendFunctions;
  updateAuthority: (
    input: UpdateAuthorityInput
  ) => ReturnType<typeof getUpdateAuthorityInstruction> & SelfPlanAndSendFunctions;
  updateAuths: (
    input: UpdateAuthsInput
  ) => ReturnType<typeof getUpdateAuthsInstruction> & SelfPlanAndSendFunctions;
  updateExchangePrice: (
    input: UpdateExchangePriceInput
  ) => ReturnType<typeof getUpdateExchangePriceInstruction> & SelfPlanAndSendFunctions;
  updateGuardians: (
    input: UpdateGuardiansInput
  ) => ReturnType<typeof getUpdateGuardiansInstruction> & SelfPlanAndSendFunctions;
  updateRateDataV1: (
    input: UpdateRateDataV1Input
  ) => ReturnType<typeof getUpdateRateDataV1Instruction> & SelfPlanAndSendFunctions;
  updateRateDataV2: (
    input: UpdateRateDataV2Input
  ) => ReturnType<typeof getUpdateRateDataV2Instruction> & SelfPlanAndSendFunctions;
  updateRevenueCollector: (
    input: UpdateRevenueCollectorInput
  ) => ReturnType<typeof getUpdateRevenueCollectorInstruction> & SelfPlanAndSendFunctions;
  updateTokenConfig: (
    input: UpdateTokenConfigInput
  ) => ReturnType<typeof getUpdateTokenConfigInstruction> & SelfPlanAndSendFunctions;
  updateUserBorrowConfig: (
    input: UpdateUserBorrowConfigInput
  ) => ReturnType<typeof getUpdateUserBorrowConfigInstruction> & SelfPlanAndSendFunctions;
