export type LiquidityPluginPdas = {
  claimAccount: typeof findClaimAccountPda;
  liquidity: typeof findLiquidityPda;
  authList: typeof findAuthListPda;
  userSupplyPosition: typeof findUserSupplyPositionPda;
  userBorrowPosition: typeof findUserBorrowPositionPda;
  rateModel: typeof findRateModelPda;
  tokenReserve: typeof findTokenReservePda;
};

export type LiquidityPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function liquidityProgram() {
  return <T extends LiquidityPluginRequirements>(
    client: T
  ): ExtendedClient<T, { liquidity: LiquidityPlugin }> => {
    return extendClient(client, {
      liquidity: <LiquidityPlugin>{
        accounts: {
          authorizationList: addSelfFetchFunctions(client, getAuthorizationListCodec()),
          liquidity: addSelfFetchFunctions(client, getLiquidityCodec()),
          rateModel: addSelfFetchFunctions(client, getRateModelCodec()),
          tokenReserve: addSelfFetchFunctions(client, getTokenReserveCodec()),
          userBorrowPosition: addSelfFetchFunctions(client, getUserBorrowPositionCodec()),
          userClaim: addSelfFetchFunctions(client, getUserClaimCodec()),
          userSupplyPosition: addSelfFetchFunctions(client, getUserSupplyPositionCodec()),
        },
        instructions: {
          changeStatus: (input) =>
            addSelfPlanAndSendFunctions(client, getChangeStatusInstruction(input)),
          claim: (input) => addSelfPlanAndSendFunctions(client, getClaimInstruction(input)),
          closeClaimAccount: (input) =>
            addSelfPlanAndSendFunctions(client, getCloseClaimAccountInstruction(input)),
          collectRevenue: (input) =>
            addSelfPlanAndSendFunctions(client, getCollectRevenueInstructionAsync(input)),
          initClaimAccount: (input) =>
            addSelfPlanAndSendFunctions(client, getInitClaimAccountInstructionAsync(input)),
          initLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getInitLiquidityInstructionAsync(input)),
          initNewProtocol: (input) =>
            addSelfPlanAndSendFunctions(client, getInitNewProtocolInstructionAsync(input)),
          initTokenReserve: (input) =>
            addSelfPlanAndSendFunctions(client, getInitTokenReserveInstructionAsync(input)),
          operate: (input) => addSelfPlanAndSendFunctions(client, getOperateInstruction(input)),
          pauseToken: (input) =>
            addSelfPlanAndSendFunctions(client, getPauseTokenInstruction(input)),
          pauseUser: (input) => addSelfPlanAndSendFunctions(client, getPauseUserInstruction(input)),
          preOperate: (input) =>
            addSelfPlanAndSendFunctions(client, getPreOperateInstruction(input)),
          unpauseToken: (input) =>
            addSelfPlanAndSendFunctions(client, getUnpauseTokenInstruction(input)),
          unpauseUser: (input) =>
            addSelfPlanAndSendFunctions(client, getUnpauseUserInstruction(input)),
          updateAuthority: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateAuthorityInstruction(input)),
          updateAuths: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateAuthsInstruction(input)),
          updateExchangePrice: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateExchangePriceInstruction(input)),
          updateGuardians: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateGuardiansInstruction(input)),
          updateRateDataV1: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateRateDataV1Instruction(input)),
          updateRateDataV2: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateRateDataV2Instruction(input)),
          updateRevenueCollector: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateRevenueCollectorInstruction(input)),
          updateTokenConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateTokenConfigInstruction(input)),
          updateUserBorrowConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateUserBorrowConfigInstruction(input)),
          updateUserClass: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateUserClassInstruction(input)),
          updateUserSupplyConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateUserSupplyConfigInstruction(input)),
          updateUserWithdrawalLimit: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateUserWithdrawalLimitInstruction(input)),
        },
        pdas: {
          claimAccount: findClaimAccountPda,
          liquidity: findLiquidityPda,
          authList: findAuthListPda,
          userSupplyPosition: findUserSupplyPositionPda,
          userBorrowPosition: findUserBorrowPositionPda,
          rateModel: findRateModelPda,
          tokenReserve: findTokenReservePda,
        },
        identifyAccount: identifyLiquidityAccount,
        identifyInstruction: identifyLiquidityInstruction,
        parseInstruction: parseLiquidityInstruction,
      },
    });
  };
}
